package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeOrder attempts to prevent injection in ORDER BY clauses
func sanitizeOrder(input string) string {
	// Strip comments and semicolons
	input = strings.ReplaceAll(input, "--", "")
	input = strings.ReplaceAll(input, ";", "")
	input = strings.ReplaceAll(input, "/*", "")
	return input
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	valid := []string{"electronics", "clothing", "food", "toys", "books"}
	for _, v := range valid {
		if strings.EqualFold(v, cat) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortCol := r.URL.Query().Get("sort")
	dir := r.URL.Query().Get("dir")

	if category == "" {
		category = "electronics"
	}

	if !validateCategory(category) {
		http.Error(w, "invalid category", 400)
		return
	}

	if dir == "" {
		dir = "ASC"
	}
	dir = strings.ToUpper(dir)
	if dir != "ASC" && dir != "DESC" {
		dir = "ASC"
	}

	// Default sort column
	if sortCol == "" {
		sortCol = "name"
	}

	// Apply sanitization to sort column
	sortCol = sanitizeOrder(sortCol)

	// Build query - category is validated, sort is "sanitized"
	query := fmt.Sprintf(
		"SELECT id, name, price, sku FROM products WHERE category = $1 ORDER BY %s %s LIMIT 50",
		sortCol, dir,
	)

	rows, err := db.Query(query, category)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
